  },
  "protocol": [
    {
      "rec": {
        "name": "SEARCH_LOOP",
        "body": [
          { "act": { "cap": "search", "by": "agent" } },
          {
            "choice": {
              "by": "agent",
              "observed": true,
              "branches": {
                "found": [
                  { "goal": { "cmp": ["found_flag", "==", 1] } }
                ],
                "not_found": [
                  { "goal": { "cmp": ["found_flag", "==", 0] } },
                  { "continue": "SEARCH_LOOP" }
                ]
              }
            }
          }
        ]
      }
    },
    { "act": { "cap": "deliver", "by": "agent" } }
  ],
  "goal": "answer_delivered",
  "init_true": [],
  "init_constraints": [
    {
      "or": [
        { "cmp": ["found_flag", "==", 0] },
        { "cmp": ["found_flag", "==", 1] }
      ]
    }
  ]
}

